/**
 * Copies of the page Instagram serves at /p/<code>/embed/captioned/,
 * trimmed to three children.
 *
 * The URLs keep their shape and lose their signature noise; the children
 * are cut from seventeen to three. What is exactly as it arrived is the
 * wrapping — JSON inside a JSON string inside a script tag — because
 * that wrapping is the only thing the parser has to find its way
 * through, and a fixture that simplified it would test nothing.
 */
export const INSTAGRAM_CAROUSEL_EMBED = "<!DOCTYPE html><html><body><div class=\"Embed\"><script type=\"application/json\" data-sjs>{\"require\":[[\"ScheduledServerJS\",\"handle\",null,[{\"__bbox\":{\"require\":[[\"RelayPrefetchedStreamCache\",\"next\",[],[\"adp_PolarisEmbedSimpleRootQueryRelayPreloader\",{\"__bbox\":{\"contextJSON\":\"{\\\"gql_data\\\": {\\\"shortcode_media\\\": {\\\"__typename\\\": \\\"GraphSidecar\\\", \\\"shortcode\\\": \\\"AAAAAAAAAAA\\\", \\\"is_video\\\": false, \\\"display_url\\\": \\\"https://scontent.cdninstagram.com/v/t51.82787-15/100000001_100000000000000001_1000000000000000001_n.jpg?stp=dst-jpg_e35_tt6&_nc_cat=100&ig_cache_key=AAAAAAAAAAAAAAAAAAAAAAAAAA%3D%3D.3-ccb7-5&ccb\\\", \\\"dimensions\\\": {\\\"height\\\": 1782, \\\"width\\\": 1412}, \\\"owner\\\": {\\\"username\\\": \\\"someone\\\"}, \\\"edge_sidecar_to_children\\\": {\\\"edges\\\": [{\\\"node\\\": {\\\"display_url\\\": \\\"https://scontent.cdninstagram.com/v/t51.82787-15/100000001_100000000000000001_1000000000000000001_n.jpg?stp=dst-jpg_e35_tt6&_nc_cat=100&ig_cache_key=AAAAAAAAAAAAAAAAAAAAAAAAAA%3D%3D.3-ccb7-5&ccb\\\", \\\"dimensions\\\": {\\\"height\\\": 1782, \\\"width\\\": 1412}, \\\"is_video\\\": false}}, {\\\"node\\\": {\\\"display_url\\\": \\\"https://scontent.cdninstagram.com/v/t51.82787-15/100000002_100000000000000002_1000000000000000002_n.jpg?stp=dst-jpg_e35_tt6&_nc_cat=100&ig_cache_key=BBBBBBBBBBBBBBBBBBBBBBBBBB%3D%3D.3-ccb7-5&ccb\\\", \\\"dimensions\\\": {\\\"height\\\": 1805, \\\"width\\\": 1438}, \\\"is_video\\\": false}}, {\\\"node\\\": {\\\"display_url\\\": \\\"https://scontent.cdninstagram.com/v/t51.82787-15/100000003_100000000000000003_1000000000000000003_n.jpg?stp=dst-jpg_e35_tt6&_nc_cat=100&ig_cache_key=CCCCCCCCCCCCCCCCCCCCCCCCCC%3D%3D.3-ccb7-5&ccb=\\\", \\\"dimensions\\\": {\\\"height\\\": 1854, \\\"width\\\": 1469}, \\\"is_video\\\": false}}]}}}}\"}}]]]}}]]]}</script></body></html>";

